// Build the Anthropic /v1/messages request payload for email classification.
// Forces a single tool_use call so Claude returns structured output.

const msg = $json;

// Pull headers into a flat map
const headers = {};
(msg.payload?.headers || []).forEach(h => { headers[h.name.toLowerCase()] = h.value; });

const subject  = headers['subject']  || '(no subject)';
const fromHdr  = headers['from']     || '(unknown)';
const received = headers['date']     || new Date().toISOString();

// Parse "Name <email@x.com>" into name + email
let senderName  = '';
let senderEmail = fromHdr;
const m = fromHdr.match(/^(.*?)\s*<([^>]+)>\s*$/);
if (m) { senderName = m[1].replace(/"/g, '').trim(); senderEmail = m[2].trim(); }

// Walk the payload to extract a text body. Prefer text/plain, fall back to text/html stripped.
function findBody(payload) {
  if (!payload) return '';
  if (payload.body?.data) {
    try { return Buffer.from(payload.body.data, 'base64').toString('utf-8'); } catch { return ''; }
  }
  if (payload.parts) {
    // Prefer text/plain
    const plain = payload.parts.find(p => p.mimeType === 'text/plain');
    if (plain) return findBody(plain);
    // Fall back to text/html
    const html = payload.parts.find(p => p.mimeType === 'text/html');
    if (html) return findBody(html).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    // Recurse
    for (const p of payload.parts) {
      const got = findBody(p);
      if (got) return got;
    }
  }
  return '';
}

let body = findBody(msg.payload).trim();
// Truncate to keep token costs sane — full body is in DB if we ever need it
const maxBody = 4000;
if (body.length > maxBody) body = body.slice(0, maxBody) + '\n\n[truncated]';

const userMessage = `Email to triage:\n\nFROM: ${fromHdr}\nSUBJECT: ${subject}\nRECEIVED: ${received}\n\nBODY:\n${body || '(empty)'}`;

const system = `You triage Mark's personal inbox. He's in Toronto, runs Sophax Consulting and Stonefield Mortgage. This is his PERSONAL Gmail (freedman.m88@gmail.com).

Classify each email and recommend an action. Be aggressive about archiving newsletters, receipts, and notifications. Be careful with anything from real humans — when in doubt, classify as 'fyi' rather than 'spam'.

Use the classify_email tool. Always.`;

const tools = [{
  name: 'classify_email',
  description: 'Classify the email and recommend an action.',
  input_schema: {
    type: 'object',
    properties: {
      classification: {
        type: 'string',
        enum: ['urgent','action','reply_needed','fyi','newsletter','receipt','calendar','spam'],
        description: 'Primary category. urgent=needs action <24h. action=needs action this week. reply_needed=human waiting for reply. fyi=informational, no action. newsletter=marketing/digest. receipt=transactional. calendar=invite/booking. spam=junk.'
      },
      urgency_score:    { type: 'integer', minimum: 0, maximum: 100, description: '0=ignore, 100=interrupt-now-urgent' },
      reasoning:        { type: 'string', description: 'One sentence explaining the classification' },
      suggested_action: {
        type: 'string',
        enum: ['none','archive','label_only','reply','flag_for_review'],
        description: 'What to do. archive for newsletters/receipts/spam. flag_for_review when uncertain. reply when human-to-human action needed.'
      }
    },
    required: ['classification','urgency_score','reasoning','suggested_action']
  }
}];

return [{
  json: {
    body: {
      model:       'claude-sonnet-4-5-20250929',
      max_tokens:  512,
      system,
      tools,
      tool_choice: { type: 'tool', name: 'classify_email' },
      messages:    [{ role: 'user', content: userMessage }]
    },
    // Carry through for downstream nodes
    gmail_message_id: msg.id,
    gmail_thread_id:  msg.threadId,
    subject,
    sender_email:     senderEmail,
    sender_name:      senderName,
    received_at:      received,
    snippet:          msg.snippet || '',
    gmail_account_id: $('Get Gmail Account').first().json.id
  }
}];

// Extract the classify_email tool_use block from Claude's response.
const resp = $json;
const trigger = $('Build Classify Request').first().json;

const toolUse = (resp.content || []).find(b => b.type === 'tool_use' && b.name === 'classify_email');
if (!toolUse) {
  throw new Error('Claude did not return a classify_email tool_use block');
}

const out = toolUse.input;

return [{
  json: {
    classification:    out.classification,
    urgency_score:     out.urgency_score,
    reasoning:         out.reasoning,
    suggested_action:  out.suggested_action,
    is_urgent:         out.classification === 'urgent' || out.urgency_score >= 80,
    would_archive:     ['newsletter','receipt','spam'].includes(out.classification),
    // Pass through email metadata
    gmail_message_id:  trigger.gmail_message_id,
    gmail_thread_id:   trigger.gmail_thread_id,
    subject:           trigger.subject,
    sender_email:      trigger.sender_email,
    sender_name:       trigger.sender_name,
    received_at:       trigger.received_at,
    snippet:           trigger.snippet,
    gmail_account_id:  trigger.gmail_account_id,
    model:             trigger.body.model
  }
}];
